CREATE TABLE public.campus_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,category text NOT NULL DEFAULT 'Facility',latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),accessible boolean NOT NULL DEFAULT false,accessibility_note text NOT NULL DEFAULT '',verified_by uuid NOT NULL DEFAULT auth.uid()); GRANT SELECT,INSERT,UPDATE ON public.campus_locations TO authenticated; GRANT ALL ON public.campus_locations TO service_role; ALTER TABLE public.campus_locations ENABLE ROW LEVEL SECURITY; CREATE POLICY "verified locations read" ON public.campus_locations FOR SELECT TO authenticated USING(true); CREATE POLICY "approved locations manage" ON public.campus_locations FOR ALL TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin') AND verified_by=auth.uid());
CREATE TABLE public.campus_parking_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),area text NOT NULL,number integer NOT NULL CHECK(number>0),occupied boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(area,number)); GRANT SELECT,INSERT,UPDATE ON public.campus_parking_slots TO authenticated; GRANT ALL ON public.campus_parking_slots TO service_role; ALTER TABLE public.campus_parking_slots ENABLE ROW LEVEL SECURITY; CREATE POLICY "parking inventory read" ON public.campus_parking_slots FOR SELECT TO authenticated USING(true); CREATE POLICY "approved parking manage" ON public.campus_parking_slots FOR ALL TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin'));
CREATE FUNCTION public.deliver_personal_reminders() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE delivered integer; BEGIN WITH due AS (UPDATE public.campus_schedule SET reminder_at=NULL WHERE user_id=auth.uid() AND reminder_at<=now() AND ends_at>now() RETURNING *) INSERT INTO public.campus_notifications(user_id,title,body,kind) SELECT user_id,title,location||' · '||starts_at::text,'Class reminder' FROM due; GET DIAGNOSTICS delivered=ROW_COUNT; RETURN delivered; END $$; REVOKE ALL ON FUNCTION public.deliver_personal_reminders() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.deliver_personal_reminders() TO authenticated;
CREATE FUNCTION public.notify_incident_response() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.campus_notifications(user_id,title,body,kind) SELECT user_id,'Security response: '||NEW.status,NEW.note,'Emergency' FROM public.incident_reports WHERE id=NEW.incident_id; RETURN NEW; END $$; CREATE TRIGGER notify_incident_response AFTER INSERT OR UPDATE ON public.incident_responses FOR EACH ROW EXECUTE FUNCTION public.notify_incident_response();
CREATE FUNCTION public.notify_security_incident() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.campus_notifications(user_id,title,body,kind) SELECT DISTINCT user_id,'New campus incident',NEW.category||' · '||left(NEW.description,200),'Emergency' FROM public.campus_permissions WHERE capability IN ('security','admin'); RETURN NEW; END $$; CREATE TRIGGER notify_security_incident AFTER INSERT ON public.incident_reports FOR EACH ROW EXECUTE FUNCTION public.notify_security_incident();